create table public.party_score_adjustments(id uuid primary key default gen_random_uuid(),party_id uuid not null references public.parties(id) on delete cascade,party_member_id uuid not null references public.party_members(id) on delete cascade,author_id uuid not null references auth.users(id) on delete restrict,delta integer not null check(delta<>0),created_at timestamptz not null default now());
alter table public.party_score_adjustments enable row level security;
revoke all on table public.party_score_adjustments from public,anon,authenticated;

create function public.finish_game_session(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.id=p_party_id and party.host_id=p_host_id and session.revision=p_expected_revision for update of session; if not found or exists(select 1 from public.picture_caption_rounds round where round.game_session_id=session_record.id and round.state='active') then raise exception using errcode='40001',message='session_not_finishable'; end if; update public.game_sessions set state='finished',joining_open=false,revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'finish_game_session',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; end; $$;
create function public.adjust_party_score(p_host_id uuid,p_party_id uuid,p_member_id uuid,p_command_id uuid,p_expected_revision bigint,p_delta integer) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.id=p_party_id and party.host_id=p_host_id and session.state='finished' and session.revision=p_expected_revision for update of session; if not found or p_delta=0 then raise exception using errcode='40001',message='stale_revision'; end if; update public.party_members set score=score+p_delta where id=p_member_id and party_id=p_party_id; if not found then raise exception using errcode='P0002',message='member_not_found'; end if; insert into public.party_score_adjustments(party_id,party_member_id,author_id,delta) values(p_party_id,p_member_id,p_host_id,p_delta); update public.game_sessions set revision=revision+1 where id=session_record.id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'adjust_party_score',jsonb_build_object('gameSessionId',session_record.id,'sessionRevision',next_revision)); return query select session_record.id,next_revision; end; $$;
create function public.create_successor_game_session(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing jsonb; prior_session public.game_sessions; successor_id uuid; next_revision bigint; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing->>'gameSessionId')::uuid,(existing->>'sessionRevision')::bigint; return; end if; select session.* into prior_session from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.id=p_party_id and party.host_id=p_host_id and session.state='finished' and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; insert into public.game_sessions(party_id,state,joining_open) values(p_party_id,'lobby',true) returning id into successor_id; update public.parties set current_game_session_id=successor_id where id=p_party_id; update public.party_members set ready=false where party_id=p_party_id and access_status='joined'; select revision into next_revision from public.game_sessions where id=successor_id; insert into public.command_receipts values(p_host_id,p_command_id,'create_successor_game_session',jsonb_build_object('gameSessionId',successor_id,'sessionRevision',next_revision)); return query select successor_id,next_revision; end; $$;
create function public.delete_party(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint) returns boolean language plpgsql security definer set search_path='' as $$ declare existing jsonb; session_record public.game_sessions; begin select response into existing from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return true; end if; select session.* into session_record from public.parties party join public.game_sessions session on session.id=party.current_game_session_id where party.id=p_party_id and party.host_id=p_host_id and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; delete from public.parties where id=p_party_id and host_id=p_host_id; return found; end; $$;
revoke all on function public.finish_game_session(uuid,uuid,uuid,bigint),public.adjust_party_score(uuid,uuid,uuid,uuid,bigint,integer),public.create_successor_game_session(uuid,uuid,uuid,bigint),public.delete_party(uuid,uuid,uuid,bigint) from public,anon,authenticated;
grant execute on function public.finish_game_session(uuid,uuid,uuid,bigint),public.adjust_party_score(uuid,uuid,uuid,uuid,bigint,integer),public.create_successor_game_session(uuid,uuid,uuid,bigint),public.delete_party(uuid,uuid,uuid,bigint) to service_role;